svg.script:
(function () {
  "use strict";

  var svg    = document.getElementById("network-svg");
  var LAYOUT = JSON.parse(document.getElementById("layout-data").textContent);
  var TREE   = LAYOUT.tree;    // node id -> [child id, ...] (primary spanning tree)
  var DEPTH  = LAYOUT.depth;   // node id -> hop count from SELF
  var LINKS  = LAYOUT.links;   // [ [src, tgt], ... ] - every edge, tree and extra

  var collapsed = {};   // node id -> true, for nodes the user collapsed

  // Every node reachable from SELF without descending through a collapsed
  // node. A collapsed node itself stays visible (so its badge can be
  // clicked again); its descendants do not.
  function visibleSet() {
    var visible = {};
    (function walk(node) {
      visible[node] = true;
      if (collapsed[node]) return;
      (TREE[node] || []).forEach(walk);
    })("SELF");
    return visible;
  }

  // Mirrors assign_lane() in src/api.py: one vertical slot per visible
  // terminus, internal nodes sit at the midpoint of their children's range.
  function assignLanes(visible) {
    var lane = {};
    var leafCounter = 0;
    (function visit(node) {
      var kids = (collapsed[node] ? [] : (TREE[node] || [])).filter(function (k) { return visible[k]; });
      if (!kids.length) {
        lane[node] = leafCounter;
        leafCounter += 1;
      } else {
        kids.forEach(visit);
        lane[node] = (lane[kids[0]] + lane[kids[kids.length - 1]]) / 2;
      }
    })("SELF");
    return { lane: lane, leaves: Math.max(leafCounter, 1) };
  }

  function elbowPath(x1, y1, x2, y2) {
    var dy = y2 - y1;
    if (Math.abs(dy) < 0.01) return "M" + x1 + "," + y1 + " L" + x2 + "," + y2;
    var run = Math.min(Math.abs(dy), x2 - x1);
    var xa  = x2 - run;
    return "M" + x1 + "," + y1 + " L" + xa + "," + y1 + " L" + x2 + "," + y2;
  }

  function relayout() {
    var visible  = visibleSet();
    var res      = assignLanes(visible);
    var lane     = res.lane;
    var leaves   = res.leaves;

    var maxDepth = 0;
    for (var id in visible) maxDepth = Math.max(maxDepth, DEPTH[id] || 0);

    var levelMinW = {};
    LINKS.forEach(function (link) {
      var src = link[0], tgt = link[1];
      if (!visible[src] || !visible[tgt] || !(src in lane) || !(tgt in lane)) return;
      var d  = DEPTH[src] || 0;
      var dy = Math.abs(lane[tgt] - lane[src]) * LAYOUT.laneH;
      var w  = Math.max(LAYOUT.hopStep, dy + LAYOUT.junctionPad);
      levelMinW[d] = Math.max(levelMinW[d] || LAYOUT.hopStep, w);
    });

    var xAtDepth = [LAYOUT.padX];
    for (var d2 = 0; d2 <= maxDepth; d2++) {
      xAtDepth[d2 + 1] = xAtDepth[d2] + (levelMinW[d2] || LAYOUT.hopStep);
    }

    var pos = {};
    for (var nid in lane) {
      pos[nid] = [xAtDepth[DEPTH[nid] || 0], LAYOUT.padY + lane[nid] * LAYOUT.laneH];
    }

    var canvasW = Math.max(LAYOUT.canvasWMin, Math.round(xAtDepth[maxDepth + 1] + LAYOUT.labelRoom));
    // Mirrors the last_row_clearance/legend_h/BOTTOM_PAD sum in render_network_svg()
    // - the legend panel is anchored to the bottom, so it has to be part of this.
    var contentH = LAYOUT.padY + (leaves - 1) * LAYOUT.laneH + 24 + LAYOUT.legendH + LAYOUT.bottomPad;
    var canvasH  = Math.max(LAYOUT.canvasHMin, Math.round(contentH));

    var nodes = svg.querySelectorAll(".node");
    for (var i = 0; i < nodes.length; i++) {
      var g  = nodes[i];
      var id2 = g.getAttribute("data-id");
      if (Object.prototype.hasOwnProperty.call(pos, id2)) {
        g.style.display = "";
        g.setAttribute("transform", "translate(" + pos[id2][0].toFixed(2) + "," + pos[id2][1].toFixed(2) + ")");
        var label = g.querySelector(".collapse-icon-label");
        if (label) {
          label.textContent = collapsed[id2] ? g.getAttribute("data-descendants") : "−";
        }
      } else {
        g.style.display = "none";
      }
    }

    var edges = svg.querySelectorAll(".edge");
    for (var j = 0; j < edges.length; j++) {
      var p   = edges[j];
      var src2 = p.getAttribute("data-src");
      var tgt2 = p.getAttribute("data-tgt");
      if (Object.prototype.hasOwnProperty.call(pos, src2) && Object.prototype.hasOwnProperty.call(pos, tgt2)) {
        p.style.display = "";
        p.setAttribute("d", elbowPath(pos[src2][0], pos[src2][1], pos[tgt2][0], pos[tgt2][1]));
      } else {
        p.style.display = "none";
      }
    }

    svg.setAttribute("width", canvasW);
    svg.setAttribute("height", canvasH);
    svg.setAttribute("viewBox", "0 0 " + canvasW + " " + canvasH);

    ["bg-grad-rect", "bg-dots-rect", "titlebar-rect"].forEach(function (elId) {
      var el = document.getElementById(elId);
      if (el) { el.setAttribute("width", canvasW); el.setAttribute("height", canvasH >= 58 ? el.getAttribute("height") : canvasH); }
    });
    document.getElementById("bg-grad-rect").setAttribute("height", canvasH);
    document.getElementById("bg-dots-rect").setAttribute("height", canvasH);
    var rule = document.getElementById("titlebar-rule");
    if (rule) rule.setAttribute("x2", canvasW);
    var titleEl = document.getElementById("title-text");
    if (titleEl) titleEl.setAttribute("x", canvasW / 2);
    var subEl = document.getElementById("subtitle-text");
    if (subEl) subEl.setAttribute("x", canvasW / 2);
    var footEl = document.getElementById("footer-text");
    if (footEl) { footEl.setAttribute("x", canvasW - 12); footEl.setAttribute("y", canvasH - 8); }
    var legendEl = document.getElementById("legend-group");
    if (legendEl) legendEl.setAttribute("transform", "translate(0," + (canvasH - LAYOUT.legendH - 20) + ")");
  }

  svg.addEventListener("click", function (ev) {
    var icon = ev.target.closest && ev.target.closest(".collapse-icon");
    if (!icon) return;
    ev.preventDefault();
    ev.stopPropagation();
    var g  = icon.closest(".node");
    var id = g.getAttribute("data-id");
    if (collapsed[id]) {
      delete collapsed[id];
    } else {
      collapsed[id] = true;
    }
    relayout();
  });

  relayout();
})();
